'use client';
import { useState, useEffect } from 'react';
import { FileUpload } from '@/components/FileUpload';
import { ProgressBar } from '@/components/ProgressBar';
import { Button } from '@/components/ui/button';
import { Download, AlertTriangle, CheckCircle, XCircle, Loader2 } from 'lucide-react';
import axios from 'axios';
import { cn } from '@/lib/utils';
import Link from 'next/link';

interface ValidationStats {
    total: number;
    processed: number;
    valid: number;
    invalid: number;
    risky: number;
}

export default function Dashboard() {
    const [jobId, setJobId] = useState<string | null>(null);
    const [status, setStatus] = useState<string>('idle');
    const [stats, setStats] = useState<ValidationStats>({ total: 0, processed: 0, valid: 0, invalid: 0, risky: 0 });
    const [error, setError] = useState<string | null>(null);
    const [results, setResults] = useState<any[]>([]);

    useEffect(() => {
        let interval: NodeJS.Timeout;
        if (jobId && status !== 'completed' && status !== 'failed') {
            interval = setInterval(async () => {
                try {
                    const res = await axios.get(`http://localhost:3001/api/status/${jobId}`);
                    const data = res.data;
                    setStatus(data.state);

                    // Estimate or get stats from progress/result
                    // Since progress is just a number, we simulate stats for live view if result is null
                    // Or if backend returned partial stats (not implemented in queue yet, but we can infer)

                    if (data.result) {
                        const resList = data.result;
                        const valid = resList.filter((r: any) => r.status === 'valid').length;
                        const invalid = resList.filter((r: any) => r.status === 'invalid').length;
                        const risky = resList.filter((r: any) => r.status === 'risky').length;
                        setStats({
                            total: resList.length,
                            processed: resList.length,
                            valid,
                            invalid,
                            risky
                        });
                        setResults(resList);
                    } else {
                        // Update progress only
                        setStats(prev => ({ ...prev, processed: Math.floor((data.progress / 100) * prev.total) }));
                    }

                    if (data.state === 'failed') {
                        setError("Validation job failed.");
                        clearInterval(interval);
                    }
                } catch (err) {
                    console.error(err);
                }
            }, 1000);
        }
        return () => clearInterval(interval);
    }, [jobId, status]);

    const handleUploadStart = (id: string, total: number) => {
        setJobId(id);
        setStats({ total, processed: 0, valid: 0, invalid: 0, risky: 0 });
        setStatus('active');
        setError(null);
    };

    const downloadReport = (type: 'valid' | 'invalid' | 'full') => {
        if (!results.length) return;

        let dataToExport = results;
        if (type === 'valid') dataToExport = results.filter(r => r.status === 'valid');
        if (type === 'invalid') dataToExport = results.filter(r => r.status === 'invalid');

        const csvContent = "data:text/csv;charset=utf-8,"
            + "Email,Status,Reason\n"
            + dataToExport.map(e => `${e.email},${e.status},${e.reason || ''}`).join("\n");

        const encodedUri = encodeURI(csvContent);
        const link = document.createElement("a");
        link.setAttribute("href", encodedUri);
        link.setAttribute("download", `email_report_${type}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const progress = stats.total > 0 ? Math.round((stats.processed / stats.total) * 100) : 0;

    return (
        <div className="min-h-screen bg-slate-50 p-6 md:p-12 font-sans">
            <header className="max-w-5xl mx-auto mb-10 flex justify-between items-center">
                <Link href="/">
                    <h1 className="text-2xl font-bold text-slate-800 tracking-tight">EmailValidator <span className="text-indigo-600">Dashboard</span></h1>
                </Link>
            </header>

            <main className="max-w-4xl mx-auto">
                {status === 'idle' && (
                    <div className="bg-white rounded-2xl shadow-xl shadow-slate-200/50 p-8 border border-slate-100">
                        <h2 className="text-xl font-semibold mb-6 text-center text-slate-700">Upload Your List</h2>
                        <FileUpload onUploadStart={handleUploadStart} onError={setError} />
                        {error && <div className="text-red-500 text-center mt-4 bg-red-50 p-2 rounded">{error}</div>}
                    </div>
                )}

                {(status === 'active' || status === 'completed' || status === 'delayed' || status === 'waiting') && (
                    <div className="space-y-6">
                        <div className="bg-white rounded-2xl shadow-lg p-8 border border-slate-100">
                            <div className="flex justify-between items-center mb-4">
                                <h2 className="text-lg font-semibold text-slate-700">
                                    {status === 'completed' ? 'Analysis Complete' : 'Processing...'}
                                </h2>
                                {status !== 'completed' && <Loader2 className="animate-spin text-indigo-500" />}
                            </div>

                            <ProgressBar progress={progress} />

                            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-8">
                                <StatCard label="Total" value={stats.total} color="bg-slate-100 text-slate-600" />
                                <StatCard label="Valid" value={stats.valid} color="bg-green-50 text-green-600" icon={<CheckCircle className="w-4 h-4" />} />
                                <StatCard label="Invalid" value={stats.invalid} color="bg-red-50 text-red-600" icon={<XCircle className="w-4 h-4" />} />
                                <StatCard label="Risky" value={stats.risky} color="bg-yellow-50 text-yellow-600" icon={<AlertTriangle className="w-4 h-4" />} />
                            </div>
                        </div>

                        {status === 'completed' && (
                            <div className="bg-indigo-900 text-white rounded-2xl shadow-xl p-8 flex flex-col md:flex-row items-center justify-between gap-6">
                                <div>
                                    <h3 className="text-xl font-bold mb-1">Download Report</h3>
                                    <p className="text-indigo-200 text-sm">Export your cleaned list in CSV format.</p>
                                </div>
                                <div className="flex gap-3">
                                    <Button onClick={() => downloadReport('valid')} className="bg-green-500 hover:bg-green-600 border-none text-white">
                                        <Download className="w-4 h-4 mr-2" /> Valid Only
                                    </Button>
                                    <Button onClick={() => downloadReport('full')} variant="secondary">
                                        Full Report
                                    </Button>
                                </div>
                                <Button variant="ghost" className="text-indigo-200 hover:text-white" onClick={() => { setStatus('idle'); setResults([]); }}>
                                    Start New XML
                                </Button>
                            </div>
                        )}
                    </div>
                )}
            </main>
        </div>
    );
}

function StatCard({ label, value, color, icon }: any) {
    return (
        <div className={cn("p-4 rounded-xl flex flex-col items-center justify-center text-center", color)}>
            <div className="text-sm font-medium opacity-80 mb-1 flex items-center gap-1">
                {icon} {label}
            </div>
            <div className="text-3xl font-bold">{value}</div>
        </div>
    )
}
